}

#[non_exhaustive]
pub enum TransportAddr {
    Relay(RelayUrl),
    Ip(SocketAddr),
    Custom(CustomAddr),
}

pub fn ip_addrs(&self) -> impl Iterator<Item = &SocketAddr>
pub fn relay_urls(&self) -> impl Iterator<Item = &RelayUrl>
